import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"空间分析","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/space-analyzer.md","filePath":"zh-CN/user-guide/space-analyzer.md","lastUpdated":1786506886000}'),l={name:"zh-CN/user-guide/space-analyzer.md"};function o(n,a,s,d,p,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="空间分析" tabindex="-1">空间分析 <a class="header-anchor" href="#空间分析" aria-label="Permalink to &quot;空间分析&quot;">​</a></h1><p>空间分析把 Lertaro 已有的文件索引转换成类似 SpaceSniffer 的快速可视化概览。它不会扫描磁盘，因此即使多个磁盘包含数百万条目，也能迅速打开。</p><h2 id="打开空间分析" tabindex="-1">打开空间分析 <a class="header-anchor" href="#打开空间分析" aria-label="Permalink to &quot;打开空间分析&quot;">​</a></h2><p>打开 Lertaro 完整搜索窗口并让搜索框保持为空，空间分析会自动作为窗口首页显示，并呈现 Lertaro 当前已加载的全部索引。输入查询会立即切换到搜索结果，清空查询则会回到空间分析根级。使用鼠标左键双击磁盘或文件夹即可进入；使用向上箭头或任意面包屑路径可返回上级位置。</p><h2 id="查看和操作" tabindex="-1">查看和操作 <a class="header-anchor" href="#查看和操作" aria-label="Permalink to &quot;查看和操作&quot;">​</a></h2><ul><li>左侧矩形树会给较大的条目分配更大的面积，明暗表示大小占比，不同边框用于区分文件夹和文件。</li><li>右侧列表显示同一批条目并按大小降序排列，每行下方的细条表示它在当前位置可见总大小中的占比；在任意一侧选中条目，另一侧也会同步高亮。</li><li>右键单击卡片或列表行，会打开与搜索结果相同的动作菜单，包括打开、定位、复制以及适用的插件动作。</li><li>选中卡片或列表行后，可使用已配置的预览快捷键打开完整窗口的预览；预览打开后会跟随之后选中的条目。</li><li>右侧列表中无法完整显示的名称会在条目被选中或悬停时滚动，而不再显示工具提示。</li></ul><h2 id="统计范围" tabindex="-1">统计范围 <a class="header-anchor" href="#统计范围" aria-label="Permalink to &quot;统计范围&quot;">​</a></h2><p>这里只包含 Lertaro 已启用索引中现有的条目，空间分析不会通过遍历文件系统来补齐缺失内容。被排除和未索引的内容不会参与统计；隐藏条目会正常显示，系统条目不会单独显示，但其大小仍可能计入可见上级文件夹的总大小。</p><p>界面显示的是文件逻辑大小，而非实际占用的磁盘空间。文件夹总大小包含其已索引的后代条目，硬链接数据只会计入一次，因此统计结果可能与 Windows 资源管理器或扇区级磁盘分析工具不同。</p><p>空间分析页面可见时会自动监听相关的内存索引变更事件，并合并连续通知后再更新。启用、禁用或删除本地索引及文件夹索引时，根视图会立即同步；进入某个目录后，只有当前目录或其后代发生变化才会重建视图，父级变化只会检查当前路径是否仍然有效。如果当前目录或任意父级被重命名、删除，或者从已启用索引中消失，空间分析会自动回退到第一个仍可用的父目录。它始终不会打开或重新加载索引缓存文件。开始搜索后会暂停空间分析更新，关闭完整搜索窗口时会释放已经渲染的条目和共用界面缓存。</p>',10)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
